import os
import re
import subprocess

import pytest

PROJECT = "/project"
VERSION_FILE = os.path.join(PROJECT, "VERSION")
RC_RE = re.compile(r"-rc\.\d+\s*$")


def _read_version():
    if not os.path.isfile(VERSION_FILE):
        pytest.skip("no VERSION file in project; requirement not applicable")
    with open(VERSION_FILE, "r", encoding="utf-8") as f:
        return f.read().strip()


def _git_dir():
    dotgit = os.path.join(PROJECT, ".git")
    if os.path.isdir(dotgit):
        return dotgit
    if os.path.isfile(dotgit):
        with open(dotgit, "r", encoding="utf-8") as f:
            content = f.read().strip()
        m = re.match(r"gitdir:\s*(.+)$", content)
        if m:
            path = m.group(1).strip()
            if not os.path.isabs(path):
                path = os.path.normpath(os.path.join(PROJECT, path))
            return path
    return None


def _current_branch():
    """Return the checked-out branch name, or None if detached/unknown."""
    gitdir = _git_dir()
    if gitdir is not None:
        head = os.path.join(gitdir, "HEAD")
        if os.path.isfile(head):
            with open(head, "r", encoding="utf-8") as f:
                content = f.read().strip()
            m = re.match(r"ref:\s*refs/heads/(.+)$", content)
            if m:
                return m.group(1).strip()
            return None  # detached HEAD
    # Fallback to git CLI
    try:
        out = subprocess.run(
            ["git", "-c", "safe.directory=*", "-C", PROJECT,
             "symbolic-ref", "--short", "-q", "HEAD"],
            capture_output=True, text=True, timeout=30,
        )
        if out.returncode == 0 and out.stdout.strip():
            return out.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        pass
    return None


def test_rc_version_requires_release_branch():
    version = _read_version()
    if not RC_RE.search(version):
        pytest.skip(f"VERSION {version!r} has no -rc.<N> suffix; not applicable")

    assert _git_dir() is not None or os.path.exists(os.path.join(PROJECT, ".git")), (
        "VERSION carries an -rc.<N> suffix but /project is not a git checkout"
    )

    branch = _current_branch()
    assert branch is not None, (
        f"VERSION {version!r} carries an -rc.<N> suffix but the checkout is on a "
        "detached HEAD, not a release/* branch"
    )
    assert branch.startswith("release/") and len(branch) > len("release/"), (
        f"VERSION {version!r} carries an -rc.<N> suffix but the checked-out "
        f"branch is {branch!r}, not a release/* branch"
    )
